import { reactive } from 'vue'
import { authApi, clearAuthToken, getAuthToken, storeAuthToken } from '../services/api'

const authState = reactive({
  user: null,
  initialized: false,
  loading: false
})

let pendingInitialization = null

async function ensureAuthenticated(forceValidation = false) {
  if (!getAuthToken()) {
    authState.user = null
    authState.initialized = true
    return false
  }
  if (!forceValidation && authState.initialized && authState.user) return true
  if (pendingInitialization) return pendingInitialization

  authState.loading = true
  pendingInitialization = authApi.getProfile()
    .then(({ user }) => {
      authState.user = user
      authState.initialized = true
      return true
    })
    .catch(() => {
      clearAuthToken()
      authState.user = null
      authState.initialized = true
      return false
    })
    .finally(() => {
      authState.loading = false
      pendingInitialization = null
    })
  return pendingInitialization
}

async function login(credentials) {
  const data = await authApi.login(credentials)
  storeAuthToken(data.token, credentials.remember)
  authState.user = data.user
  authState.initialized = true
  return data.user
}

async function logout() {
  try {
    if (getAuthToken()) await authApi.logout()
  } finally {
    clearAuthToken()
    authState.user = null
    authState.initialized = true
  }
}

function setUser(user) {
  authState.user = user
  authState.initialized = true
}

window.addEventListener('auth:unauthorized', () => {
  authState.user = null
  authState.initialized = true
})

export function useAuth() {
  return { authState, ensureAuthenticated, login, logout, setUser }
}


import { onBeforeUnmount, watch } from 'vue'

export const FORM_DRAFT_TTL_MS = 8 * 60 * 60 * 1000

const getStorage = () => {
  try {
    return window.sessionStorage
  } catch {
    return null
  }
}

export function loadFormDraft(storageKey) {
  const storage = getStorage()
  if (!storage) return null
  try {
    const raw = storage.getItem(storageKey)
    if (!raw) return null
    const payload = JSON.parse(raw)
    if (payload.version !== 1 || !payload.expiresAt || Date.now() >= payload.expiresAt) {
      storage.removeItem(storageKey)
      return null
    }
    return payload.data || null
  } catch {
    storage.removeItem(storageKey)
    return null
  }
}

export function useFormDraft(storageKey, source, { ttlMs = FORM_DRAFT_TTL_MS, debounceMs = 300 } = {}) {
  const storage = getStorage()
  let active = true
  let saveTimer = null

  const saveDraft = () => {
    if (!active || !storage) return
    try {
      const now = Date.now()
      storage.setItem(storageKey, JSON.stringify({
        version: 1,
        savedAt: now,
        expiresAt: now + ttlMs,
        data: source()
      }))
    } catch {
      // Storage can be unavailable or full; the form must remain usable either way.
    }
  }

  const scheduleSave = () => {
    if (!active) return
    window.clearTimeout(saveTimer)
    saveTimer = window.setTimeout(saveDraft, debounceMs)
  }

  const stop = watch(source, scheduleSave, { deep: true })

  const clearDraft = () => {
    active = false
    window.clearTimeout(saveTimer)
    stop()
    try { storage?.removeItem(storageKey) } catch { /* no-op */ }
  }

  onBeforeUnmount(() => {
    window.clearTimeout(saveTimer)
    if (active) saveDraft()
    stop()
  })

  return { clearDraft, saveDraft }
}


import { ref } from 'vue'

const toasts = ref([])

export const useToast = () => {
  const add = ({ severity, summary, detail, life = 3500 }) => {
    const iconMap = {
      success: 'ri-check-line',
      error: 'ri-error-warning-line',
      warning: 'ri-alert-line',
      info: 'ri-information-line'
    }
    const colorMap = {
      success: '#10b981',
      error: '#ef4444',
      warning: '#f59e0b',
      info: '#3b82f6'
    }
    const id = Date.now() + Math.random()
    toasts.value.push({
      id,
      title: summary,
      detail,
      type: severity,
      icon: iconMap[severity],
      color: colorMap[severity]
    })
    setTimeout(() => {
      toasts.value = toasts.value.filter(t => t.id !== id)
    }, life)
  }

  return { toasts, add }
}

export { toasts }


