import { createRouter, createWebHashHistory } from 'vue-router'

// Layouts
import MainLayout from '../layouts/MainLayout.vue'

// Views
import LoginView from '../views/LoginView.vue'
import DashboardView from '../views/DashboardView.vue'
import RecipientListView from '../views/RecipientListView.vue'
import RecipientCreateView from '../views/RecipientCreateView.vue'
import RecipientDetailView from '../views/RecipientDetailView.vue'
import DonorListView from '../views/DonorListView.vue'
import DonorCreateView from '../views/DonorCreateView.vue'
import DonorDetailView from '../views/DonorDetailView.vue'
import MatchingDashboardView from '../views/MatchingDashboardView.vue'
import VirtualCrossmatchView from '../views/VirtualCrossmatchView.vue'
import WaitingListRecipientsView from '../views/WaitingListRecipientsView.vue'
import UserProfileView from '../views/UserProfileView.vue'
import ForgotPasswordView from '../views/ForgotPasswordView.vue'
import ResetPasswordView from '../views/ResetPasswordView.vue'
import { useAuth } from '../composables/useAuth'

const routes = [
  { path: '/', redirect: '/login' },
  { path: '/login', name: 'login', component: LoginView, meta: { guestOnly: true } },
  { path: '/forgot-password', name: 'forgot-password', component: ForgotPasswordView },
  { path: '/reset-password', name: 'reset-password', component: ResetPasswordView },
  {
    path: '/',
    component: MainLayout,
    meta: { requiresAuth: true },
    children: [
      { path: 'dashboard', name: 'dashboard', component: DashboardView },
      { path: 'recipients', component: RecipientListView },
      { path: 'recipients/new', component: RecipientCreateView },
      { path: 'recipients/:id', component: RecipientDetailView },
      { path: 'donors', component: DonorListView },
      { path: 'donors/new', component: DonorCreateView },
      { path: 'donors/:id', component: DonorDetailView },
      { path: 'matching', component: MatchingDashboardView },
      { path: 'matching/virtual-crossmatch', component: VirtualCrossmatchView },
      { path: 'waiting-list/recipients', component: WaitingListRecipientsView },
      { path: 'profile', name: 'user-profile', component: UserProfileView }
    ]
  }
]

const router = createRouter({
  history: createWebHashHistory(),
  routes
})

router.beforeEach(async (to) => {
  const { ensureAuthenticated } = useAuth()
  const requiresAuth = to.matched.some((record) => record.meta.requiresAuth)

  // Revalidate the token with Django before every protected navigation.
  if (requiresAuth && !(await ensureAuthenticated(true))) {
    return { name: 'login', query: { redirect: to.fullPath } }
  }
  if (to.meta.guestOnly && (await ensureAuthenticated())) {
    return { name: 'dashboard' }
  }
  return true
})

export default router


const API_BASE_URL = (import.meta.env.VITE_API_BASE_URL || '/api').replace(/\/$/, '')

export class ApiError extends Error {
  constructor(message, status, data = {}) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.data = data
  }
}

export function getAuthToken() {
  return localStorage.getItem('auth_token') || sessionStorage.getItem('auth_token')
}

export function storeAuthToken(token, remember) {
  clearAuthToken()
  const storage = remember ? localStorage : sessionStorage
  storage.setItem('auth_token', token)
}

export function clearAuthToken() {
  localStorage.removeItem('auth_token')
  sessionStorage.removeItem('auth_token')
}

async function request(path, { method = 'GET', body, authenticated = true } = {}) {
  const headers = { Accept: 'application/json' }
  if (body !== undefined) headers['Content-Type'] = 'application/json'

  const token = getAuthToken()
  if (authenticated && token) headers.Authorization = `Bearer ${token}`

  let response
  try {
    response = await fetch(`${API_BASE_URL}${path}`, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body)
    })
  } catch {
    throw new ApiError('ارتباط با سرور برقرار نشد. لطفاً دوباره تلاش کنید.', 0)
  }

  const data = await response.json().catch(() => ({}))
  if (!response.ok) {
    if (response.status === 401 && authenticated) {
      clearAuthToken()
      window.dispatchEvent(new CustomEvent('auth:unauthorized'))
    }
    throw new ApiError(data.message || 'خطایی در انجام درخواست رخ داد.', response.status, data)
  }
  return data
}

export const authApi = {
  login(credentials) {
    return request('/auth/login/', { method: 'POST', body: credentials, authenticated: false })
  },
  logout() {
    return request('/auth/logout/', { method: 'POST', body: {} })
  },
  getProfile() {
    return request('/auth/me/')
  },
  updateProfile(profile) {
    return request('/auth/me/', { method: 'PATCH', body: profile })
  },
  changePassword(passwords) {
    return request('/auth/change-password/', { method: 'POST', body: passwords })
  },
  updateNotificationPreferences(preferences) {
    return request('/auth/notification-preferences/', {
      method: 'PATCH',
      body: preferences
    })
  },
  requestPasswordReset(email) {
    return request('/auth/password-reset/', {
      method: 'POST',
      body: { email },
      authenticated: false
    })
  },
  confirmPasswordReset(payload) {
    return request('/auth/password-reset/confirm/', {
      method: 'POST',
      body: payload,
      authenticated: false
    })
  }
}

export const registryApi = {
  listRecipients() {
    return request('/registry/recipients/')
  },
  getRecipient(id) {
    return request(`/registry/recipients/${id}/`)
  },
  createRecipient(payload) {
    return request('/registry/recipients/', { method: 'POST', body: payload })
  },
  listDonors() {
    return request('/registry/donors/')
  },
  getDonor(id) {
    return request(`/registry/donors/${id}/`)
  },
  createDonor(payload) {
    return request('/registry/donors/', { method: 'POST', body: payload })
  },
  checkIdentifier(citizenship, identifier) {
    const params = new URLSearchParams({ citizenship, identifier })
    return request(`/registry/identifier-availability/?${params}`)
  },
  lookupRecipient(identifier) {
    return request(`/registry/recipients/lookup/?identifier=${encodeURIComponent(identifier)}`)
  },
  lookupPerson(identifier) {
    return request(`/registry/people/lookup/?identifier=${encodeURIComponent(identifier)}`)
  },
  saveHla(personId, payload) {
    return request(`/registry/people/${personId}/hla/`, { method: 'PUT', body: payload })
  },
  createCdcPra(personId, payload) {
    return request(`/registry/people/${personId}/cdc-pra/`, { method: 'POST', body: payload })
  },
  updateCdcPra(personId, testId, payload) {
    return request(`/registry/people/${personId}/cdc-pra/${testId}/`, { method: 'PATCH', body: payload })
  },
  createAntiHla(personId, payload) {
    return request(`/registry/people/${personId}/anti-hla/`, { method: 'POST', body: payload })
  },
  updateAntiHla(personId, testId, payload) {
    return request(`/registry/people/${personId}/anti-hla/${testId}/`, { method: 'PATCH', body: payload })
  }
}


/* =====================================================================
   ۱) توکن‌های طراحی (Design Tokens)
   ---------------------------------------------------------------------
   برای تغییر تم کلی برنامه (رنگ‌ها، گوشه‌ها، سایه‌ها و گرادیان‌ها)
   فقط مقادیر این بخش را ویرایش کنید؛ هیچ استایل دیگری را تغییر ندهید.
   ===================================================================== */
:root {
  /* --- پالت برند --- */
  --brand-400: #38bdf8;
  --brand-500: #0ea5e9;
  --brand-600: #0284c7;
  --brand-700: #0369a1;
  --accent-500: #06b6d4;
  --secondary-600: #2563eb;

  /* --- رنگ‌های وضعیت --- */
  --success-500: #10b981;
  --success-700: #047857;
  --warning-500: #f59e0b;
  --warning-700: #92400e;
  --error-500: #ef4444;
  --error-700: #991b1b;
  --info-500: #3b82f6;
  --info-700: #1e40af;

  /* --- سطح‌ها و متن --- */
  --surface: #ffffff;
  --surface-ground: #f8fafc;
  --surface-muted: #f1f5f9;
  --border: #e2e8f0;
  --border-strong: #cbd5e1;
  --text-1: #0f172a;
  --text-2: #475569;
  --text-3: #94a3b8;

  /* --- توکن‌های معنایی --- */
  --color-primary: var(--brand-500);
  --color-primary-dark: var(--brand-600);
  --color-primary-light: var(--brand-400);
  --color-primary-soft: #e0f2fe;
  --color-secondary: var(--secondary-600);
  --color-accent: var(--accent-500);
  --color-success: var(--success-500);
  --color-warning: var(--warning-500);
  --color-error: var(--error-500);
  --color-info: var(--info-500);

  /* --- گرادیان‌ها --- */
  --grad-brand: linear-gradient(135deg, var(--brand-500), var(--secondary-600));
  --grad-donor: linear-gradient(135deg, var(--success-500), var(--accent-500));
  --grad-auth: linear-gradient(135deg, #0c4a6e 0%, #0369a1 50%, #06b6d4 100%);

  /* --- گوشه‌ها --- */
  --radius-sm: 8px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-xl: 18px;
  --radius-full: 999px;

  /* --- سایه‌ها --- */
  --shadow-1: 0 1px 2px rgba(15,23,42,.06);
  --shadow-2: 0 8px 20px -6px rgba(15,23,42,.12);
  --shadow-3: 0 20px 45px -12px rgba(15,23,42,.25);
  --shadow-brand: 0 10px 22px -6px rgba(14,165,233,.45);

  /* --- فونت --- */
  --font-sans: 'Vazirmatn', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

/* ---------------------------------------------------------------------
   تم جایگزین نمونه — برای آزمایش سریع، کامنت زیر را بردارید.
   (ساختار برنامه هیچ تغییری نمی‌کند)
------------------------------------------------------------------------
:root {
  --brand-400: #34d399; --brand-500: #10b981; --brand-600: #059669;
  --brand-700: #047857; --accent-500: #14b8a6; --secondary-600: #0d9488;
  --color-primary-soft: #d1fae5;
  --grad-auth: linear-gradient(135deg, #064e3b 0%, #047857 50%, #14b8a6 100%);
  --shadow-brand: 0 10px 22px -6px rgba(16,185,129,.45);
}
------------------------------------------------------------------------ */

/* ===================== ۲) استایل‌های پایه ===================== */
* { box-sizing: border-box; }
html, body {
  font-family: var(--font-sans);
  margin: 0; padding: 0;
  background: var(--surface-ground);
  color: var(--text-1);
  font-size: 14px;
  line-height: 1.7;
}
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-3); }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
@keyframes slideInLeft { from { opacity: 0; transform: translateX(-20px); } to { opacity: 1; transform: translateX(0); } }

/* ===================== ۳) صفحه ورود ===================== */
.auth-page {
  min-height: 100vh;
  display: flex; align-items: center; justify-content: center;
  background: var(--grad-auth);
  position: relative; overflow: hidden;
  padding: 24px;
}
.auth-page::before, .auth-page::after {
  content: ''; position: absolute; border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.14); pointer-events: none;
}
.auth-page::before { width: 520px; height: 520px; top: -180px; left: -140px; }
.auth-page::after  { width: 380px; height: 380px; bottom: -140px; right: -100px; background: radial-gradient(circle, rgba(255,255,255,.08), transparent 70%); }
.auth-card {
  width: 100%; max-width: 440px;
  background: var(--surface);
  border-radius: var(--radius-xl);
  padding: 38px 40px;
  box-shadow: var(--shadow-3);
  position: relative; z-index: 1;
  animation: slideUp .45s ease;
}
.auth-card::before {
  content: ''; position: absolute; top: 0; right: 24px; left: 24px; height: 4px;
  background: var(--grad-brand); border-radius: 0 0 6px 6px;
}
.auth-brand { display: flex; align-items: center; gap: 13px; margin-bottom: 26px; }
.auth-brand-icon {
  width: 50px; height: 50px; border-radius: 14px;
  background: var(--grad-brand);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 26px; box-shadow: var(--shadow-brand);
}
.auth-brand-title { font-weight: 900; font-size: 17px; }
.auth-brand-sub { font-size: 12px; color: var(--text-3); }

/* ===================== ۴) پوسته اصلی ===================== */
.app-shell {
  min-height: 100vh; display: flex;
  width: 100%; max-width: 1280px; margin-inline: auto; position: relative;
  background:
    radial-gradient(1100px 420px at 88% -8%, rgba(14,165,233,.06), transparent 60%),
    var(--surface-ground);
}
.sidebar {
  width: 260px; background: var(--surface);
  border-left: 1px solid var(--border);
  display: flex; flex-direction: column;
  position: fixed; right: max(0px, calc((100vw - 1280px) / 2)); top: 0; bottom: 0; z-index: 40;
  transition: width .3s ease; overflow: hidden;
}
.sidebar.collapsed { width: 72px; }
.sidebar.collapsed .nav-label,
.sidebar.collapsed .brand-text,
.sidebar.collapsed .nav-section-title { display: none; }
.sidebar-header {
  padding: 15px 16px; border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
}
.brand { display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0; }
.brand-icon {
  width: 38px; height: 38px; background: var(--grad-brand);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 22px; box-shadow: var(--shadow-brand); flex-shrink: 0;
}
.brand-text { font-weight: 800; font-size: 14.5px; white-space: nowrap; }
.toggle-btn {
  width: 32px; height: 32px; border-radius: var(--radius-sm);
  background: var(--surface-muted); border: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  color: var(--text-2); transition: all .2s;
}
.toggle-btn:hover { background: var(--color-primary-soft); color: var(--color-primary-dark); }
.lookup-section { padding: 12px; border-bottom: 1px solid var(--border); }
.lookup-btn {
  width: 100%; display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: var(--radius-md);
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
  border: 1px solid #bfdbfe; color: var(--color-secondary);
  cursor: pointer; font-family: inherit; font-weight: 600; transition: all .2s;
}
.lookup-btn:hover { border-color: var(--color-primary); transform: translateY(-1px); box-shadow: var(--shadow-1); }
.sidebar.collapsed .lookup-btn span { display: none; }
.sidebar-nav { flex: 1; overflow-y: auto; padding: 10px; }
.nav-section { margin-bottom: 12px; }
.nav-section-title {
  padding: 0 12px 6px; font-size: 11px; font-weight: 700;
  color: var(--text-3); letter-spacing: .5px;
}
.nav-item {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 12px; border-radius: var(--radius-sm);
  color: var(--text-2); cursor: pointer; font-family: inherit;
  background: transparent; border: none; width: 100%; text-align: right;
  transition: all .2s; font-weight: 500; margin-bottom: 2px;
}
.nav-item:hover { background: var(--surface-muted); color: var(--color-primary); }
.nav-item.active {
  background: linear-gradient(135deg, var(--color-primary-soft) 0%, #cffafe 100%);
  color: var(--color-primary-dark); font-weight: 700; position: relative;
}
.nav-item.active::before {
  content: ''; position: absolute; right: 0; top: 20%; bottom: 20%;
  width: 3px; background: var(--color-primary); border-radius: 2px;
}
.nav-icon { font-size: 20px; flex-shrink: 0; }
.nav-label { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* ---- بدنه اصلی ---- */
.main {
  flex: 1; margin-right: 260px;
  display: flex; flex-direction: column; min-height: 100vh;
  transition: margin-right .3s ease;
}
.main.collapsed { margin-right: 72px; }
.topbar {
  height: 62px; background: var(--surface);
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px; position: sticky; top: 0; z-index: 30; gap: 16px;
}
.topbar-user { display: flex; align-items: center; gap: 10px; }
.topbar-user-text { display: flex; flex-direction: column; line-height: 1.35; }
.topbar-user-name { font-size: 13px; font-weight: 700; }
.topbar-user-role { font-size: 11.5px; color: var(--text-3); }
.topbar-actions { display: flex; align-items: center; gap: 10px; margin-right: auto; }
/* تاریخ هدر — متنی ساده، کنار زنگ اعلان */
.topbar-date { display: flex; flex-direction: column; align-items: flex-start; line-height: 1.4; padding: 0 2px; }
.topbar-date-j { font-size: 12.5px; font-weight: 700; color: var(--text-1); }
.topbar-date-g { font-size: 11px; font-weight: 500; color: var(--text-3); }
.topbar-divider { width: 1px; height: 26px; background: var(--border); }
.icon-btn {
  width: 40px; height: 40px; border-radius: var(--radius-md);
  background: var(--surface-muted); border: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  color: var(--text-2); position: relative; font-size: 20px; transition: all .2s;
}
.icon-btn:hover { background: var(--color-primary-soft); color: var(--color-primary-dark); transform: translateY(-1px); }
.notif-badge {
  position: absolute; top: 4px; left: 4px;
  min-width: 18px; height: 18px; border-radius: 50%;
  background: var(--color-error); color: #fff;
  font-size: 10px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  border: 2px solid #fff;
}
/* User dropdown in header */
.user-dropdown { position: relative; }
.user-btn { width: auto; padding: 0 8px 0 6px; gap: 6px; }
.dropdown-menu {
  position: absolute; top: calc(100% + 8px); left: 0;
  min-width: 170px; background: var(--surface);
  border: 1px solid var(--border); border-radius: var(--radius-md);
  box-shadow: var(--shadow-3); z-index: 50;
  padding: 6px; overflow: hidden;
  animation: slideDown .2s ease;
}
@keyframes slideDown { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: translateY(0); } }
.dropdown-item {
  width: 100%; display: flex; align-items: center; gap: 10px;
  padding: 9px 11px; border-radius: var(--radius-sm);
  background: transparent; border: none; cursor: pointer;
  font-family: inherit; font-size: 13px; font-weight: 500;
  color: var(--text-2); text-align: right; transition: all .2s;
}
.dropdown-item:hover { background: var(--surface-muted); color: var(--color-primary); }
.dropdown-item i { font-size: 18px; }
.content { padding: 24px; flex: 1; }

/* ===================== ۵) اجزای صفحه ===================== */
.page-header {
  display: flex; justify-content: space-between; align-items: flex-start;
  margin-bottom: 22px; gap: 16px;
}
.page-title { font-size: 23px; font-weight: 900; margin-bottom: 3px; }
.page-subtitle { color: var(--text-2); font-size: 13px; }

.card {
  background: var(--surface); border-radius: var(--radius-lg);
  border: 1px solid var(--border); padding: 20px;
  box-shadow: var(--shadow-1); transition: all .2s;
}
.card-title { font-size: 15px; font-weight: 700; margin-bottom: 16px; display: flex; align-items: center; gap: 8px; }
.card-title i { color: var(--color-primary); font-size: 18px; }

.grid { display: grid; gap: 20px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

/* ---- دکمه‌ها ---- */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 10px 18px; border-radius: var(--radius-md);
  font-weight: 600; font-size: 13px; cursor: pointer;
  border: 1.5px solid transparent; font-family: inherit; transition: all .2s;
}
.btn-primary { background: var(--grad-brand); color: #fff; box-shadow: var(--shadow-brand); }
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 15px 26px -6px rgba(14,165,233,.55); }
.btn-secondary { background: var(--surface-muted); color: var(--text-1); border-color: var(--border); }
.btn-secondary:hover { background: var(--border); }
.btn-outline { background: transparent; color: var(--color-primary); border-color: var(--color-primary); }
.btn-outline:hover { background: var(--color-primary); color: #fff; }
.btn-danger { background: var(--color-error); color: #fff; }
.btn-danger:hover { background: var(--error-700); transform: translateY(-1px); }
.btn-sm { padding: 6px 12px; font-size: 12px; }
.btn-lg { padding: 12px 24px; font-size: 15px; }
.btn-block { width: 100%; justify-content: center; }
.btn-filter-active { background: var(--color-primary-soft); color: var(--color-primary-dark); border-color: var(--color-primary); }
.filter-badge { background: var(--color-primary); color: #fff; border-radius: var(--radius-full); font-size: 11px; padding: 1px 8px; font-weight: 700; }

/* ---- فرم ---- */
.form-group { margin-bottom: 18px; }
.form-label { display: block; font-size: 14.5px; font-weight: 700; margin-bottom: 8px; color: var(--text-1); line-height: 1.65; }
.form-input, .form-select {
  width: 100%; min-height: 48px; padding: 10px 14px;
  border: 2px solid var(--border); border-radius: var(--radius-md);
  background: var(--surface); font-family: inherit; font-size: 15px; line-height: 1.75;
  color: var(--text-1); transition: all .2s; outline: none;
}
.form-input::placeholder { color: var(--text-3); font-size: 13px; font-weight: 400; opacity: 1; }
.form-input:focus, .form-select:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 4px rgba(14,165,233,.12);
}
.form-error-border { border-color: var(--color-error) !important; }
.input-wrapper { position: relative; }
.input-icon { position: absolute; right: 14px; top: 50%; transform: translateY(-50%); color: var(--text-3); font-size: 18px; }
.form-error { color: var(--color-error); font-size: 13px; font-weight: 600; margin-top: 5px; }
.form-success { color: var(--color-success); font-size: 13px; font-weight: 600; margin-top: 5px; }
.input-group { display: flex; }
.input-group .form-input { border-top-left-radius: 0; border-bottom-left-radius: 0; flex: 1; }
.input-addon {
  background: var(--surface-muted); border: 2px solid var(--border); border-right: none;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  display: flex; align-items: center; padding: 0 14px; color: var(--text-3);
}

/* ---- کارت‌های فرم (چیدمان جدید فرم‌ها) ---- */
.form-card {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 22px;
  margin-bottom: 18px; box-shadow: var(--shadow-1);
  transition: border-color .2s;
}
.form-card:hover { border-color: var(--border-strong); }
.form-card-title { display: flex; align-items: center; gap: 12px; font-size: 16px; font-weight: 800; margin-bottom: 20px; }
.form-card-title i {
  color: var(--color-primary-dark); font-size: 22px;
  background: var(--color-primary-soft);
  width: 40px; height: 40px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
}
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px 20px; }
.form-grid-3 { grid-template-columns: repeat(3, 1fr); }
.form-grid-4 { grid-template-columns: repeat(4, 1fr); }
.form-grid > .form-group { min-width: 0; }
.form-actions { display: flex; justify-content: space-between; gap: 12px; padding: 18px 4px 0; margin-top: 4px; border-top: 1px solid var(--border); }

/* ---- فرم‌های ثبت گیرنده و اهداکننده ---- */
.create-person-page {
  width: 100%; max-width: 1280px; margin-inline: auto;
}
.create-person-page .form-grid {
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 16px 24px;
}
.create-person-page .form-grid > .form-group { grid-column: span 6; }
.identity-primary-grid {
  align-items: start;
}
.identity-primary-grid > .form-group { grid-column: span 6 !important; }
.identity-primary-grid.is-foreign > .form-group { grid-column: span 4 !important; }
.identity-details-grid {
  align-items: start;
  margin-top: 6px; padding-top: 22px;
  border-top: 1px solid var(--border);
}
.identity-details-grid > .form-group:nth-child(-n+3) { grid-column: span 4; }
.identity-details-grid > .form-group:nth-child(n+4) { grid-column: span 6; }
.identity-details-grid .form-group,
.contact-fields-grid .form-group,
.personal-profile-grid .form-group { margin-bottom: 0; }
.identity-birth-field .dp-mode-btn { padding-inline: 14px; }
.contact-fields-grid {
  align-items: start;
}
.personal-profile-grid {
  align-items: start;
}
.personal-profile-grid > .form-group:nth-child(-n+3) { grid-column: span 4; }
.personal-profile-grid > .measure-field { grid-column: span 6; }

/* ---- کنترل‌های انتخابی قطعه‌ای ---- */
.segmented-toggle {
  display: grid; grid-auto-flow: column; grid-auto-columns: 1fr;
  width: 100%; min-height: 48px; padding: 4px;
  background: var(--surface-muted); border: 1px solid var(--border);
  border-radius: var(--radius-md); gap: 4px;
}
.toggle-option {
  display: flex; align-items: center; justify-content: center;
  min-width: 0; padding: 7px 12px; border-radius: 8px;
  color: var(--text-2); font-size: 14px; font-weight: 700;
  cursor: pointer; transition: background .2s, color .2s, box-shadow .2s;
}
.toggle-option:hover { color: var(--color-primary-dark); }
.toggle-option.checked { background: var(--surface); color: var(--color-primary-dark); box-shadow: var(--shadow-1); }
.toggle-option input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
.toggle-option:focus-within { outline: 2px solid var(--color-primary); outline-offset: -2px; }

/* ---- وضعیت اعتبارسنجی درون فیلد ---- */
.validation-control { position: relative; }
.validation-control .form-input { padding-left: 46px; }
.validation-icon {
  position: absolute; left: 14px; top: 50%; transform: translateY(-50%);
  font-size: 21px; line-height: 1; pointer-events: none;
}
.validation-control.is-valid .form-input { border-color: var(--color-success); }
.validation-control.is-valid .validation-icon { color: var(--color-success); }
.validation-control.is-invalid .form-input { border-color: var(--color-error); }
.validation-control.is-invalid .validation-icon { color: var(--color-error); }
.validation-icon.is-loading { color: var(--color-primary); animation: spin 1s linear infinite; }
.field-feedback { display: flex; align-items: center; min-height: 22px; margin-top: 4px; font-size: 13px; font-weight: 600; }
.field-feedback.is-error { color: var(--color-error); }
.field-feedback.is-success { color: var(--success-700); }

/* ---- نمایش تدریجی رفتارهای پرخطر ---- */
.risk-disclosure { margin-top: 22px; border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden; }
.risk-disclosure-trigger {
  width: 100%; min-height: 54px; padding: 11px 16px;
  display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px;
  border: 0; background: var(--surface-muted); color: var(--text-1);
  font: inherit; font-weight: 800; text-align: right; cursor: pointer;
}
.risk-disclosure-trigger > span:first-child { display: inline-flex; align-items: center; gap: 9px; }
.risk-disclosure-trigger > span:first-child i { color: var(--color-primary); font-size: 22px; }
.risk-disclosure-summary { display: inline-flex; align-items: center; gap: 6px; color: var(--text-2); font-size: 13px; font-weight: 600; }
.risk-disclosure-caret { color: var(--color-primary-dark); font-size: 20px; transition: transform .2s; }
.risk-disclosure.open .risk-disclosure-caret { transform: rotate(180deg); }
.risk-disclosure-content { padding: 18px 16px; border-top: 1px solid var(--border); background: var(--surface); }

/* ---- ناوبری چسبان پایین فرم ---- */
.sticky-form-footer {
  position: sticky; bottom: 0; z-index: 25;
  align-items: center; margin-top: 24px; padding: 12px 18px;
  border: 1px solid var(--border); border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  background: rgba(255,255,255,.97); box-shadow: 0 -10px 28px -18px rgba(15,23,42,.45);
  backdrop-filter: blur(10px);
}
.form-action-end { display: flex; align-items: center; gap: 10px; }
.form-back-link {
  display: inline-flex; align-items: center; gap: 7px; padding: 8px 2px;
  border: 0; background: transparent; color: var(--text-2);
  font-family: inherit; font-size: 14px; font-weight: 700; cursor: pointer;
}
.form-back-link:hover { color: var(--color-primary-dark); }
.form-back-placeholder { min-width: 1px; }
.btn-cancel {
  background: transparent; border-color: var(--color-primary); color: #dc7b82;
  box-shadow: none;
}
.btn-cancel:hover { background: #fff7f7; border-color: var(--color-primary-dark); color: var(--error-700); }
.form-next-button { min-width: 170px; justify-content: center; }

/* ---- انتخاب‌های چیپی ---- */
.radio-pills { display: flex; gap: 8px; }
.radio-pill {
  flex: 1; display: flex; align-items: center; justify-content: center; gap: 6px;
  padding: 9px 12px; border: 2px solid var(--border); border-radius: var(--radius-md);
  cursor: pointer; font-size: 13px; font-weight: 600; color: var(--text-2);
  transition: all .2s; background: var(--surface);
}
.radio-pill input { display: none; }
.create-person-page .radio-pill input {
  display: block;
  appearance: none;
  width: 15px;
  height: 15px;
  flex: 0 0 15px;
  margin: 0;
  border: 1.5px solid var(--border-strong);
  border-radius: 50%;
  background: var(--surface);
  transition: border-color .2s, box-shadow .2s;
}
.create-person-page .radio-pill input:checked {
  border: 4px solid var(--color-primary);
  box-shadow: 0 0 0 2px rgba(14,165,233,.12);
}
.radio-pill:hover { border-color: var(--color-primary-light); }
.radio-pill.checked { border-color: var(--color-primary); background: var(--color-primary-soft); color: var(--color-primary-dark); }
.check-chips { display: flex; gap: 10px; flex-wrap: wrap; }
.check-chip {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 9px 16px; border: 2px solid var(--border); border-radius: var(--radius-full);
  background: var(--surface); cursor: pointer; font-size: 13px; font-weight: 600;
  color: var(--text-2); transition: all .2s;
}
.check-chip input { display: none; }
.check-chip i { font-size: 16px; color: var(--text-3); transition: color .2s; }
.check-chip:hover { border-color: var(--color-primary-light); transform: translateY(-1px); }
.check-chip.checked { border-color: var(--color-primary); background: var(--color-primary-soft); color: var(--color-primary-dark); }
.check-chip.checked i { color: var(--color-primary-dark); }
.check-chip.disabled {
  cursor: not-allowed;
  opacity: .48;
  border-color: var(--border);
  background: var(--surface-ground);
  color: var(--text-3);
  transform: none;
}
.check-chip.disabled:hover { border-color: var(--border); transform: none; }
.recipient-donor-source-hint { margin-top: 7px; color: var(--text-2); font-size: 13px; }
.cause-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.cause-chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 7px 14px; border: 1.5px solid var(--border); border-radius: var(--radius-full);
  background: var(--surface); cursor: pointer; font-size: 12.5px; font-weight: 600;
  color: var(--text-2); transition: all .2s;
}
.cause-chip input { display: none; }
.cause-chip:hover { border-color: var(--color-primary-light); transform: translateY(-1px); }
.cause-chip.checked { background: var(--color-primary-soft); border-color: var(--color-primary); color: var(--color-primary-dark); }
/* ---- اعتبارسنجی و نمایش نتایج ثبت ---- */
.required-choice-group { padding: 5px; border: 1.5px solid transparent; border-radius: var(--radius-md); transition: border-color .2s, background .2s; }
.required-choice-group.choice-error { border-color: var(--color-error); background: #fef2f2; }
.cdc-pra-card { padding: 18px; border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--surface-ground); }
.cdc-pra-card h4 { margin: 0 0 12px; }
.cdc-status-options { max-width: 300px; }
.cdc-value-field { max-width: 230px; margin: 14px 0 0; }
.input-with-suffix { display: flex; align-items: stretch; direction: ltr; }
.input-with-suffix .form-input { border-radius: var(--radius-md) 0 0 var(--radius-md); text-align: center; }
.input-with-suffix > span { min-width: 40px; display: grid; place-items: center; border: 2px solid var(--border); border-left: 0; border-radius: 0 var(--radius-md) var(--radius-md) 0; background: var(--surface-muted); color: var(--text-2); font-weight: 700; }
.compact-empty-state { padding: 22px; }
.compact-empty-state i { font-size: 32px; margin-bottom: 8px; }
.result-batches { display: flex; flex-direction: column; gap: 10px; }
.result-batch { border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--surface-ground); overflow: hidden; }
.result-batch-header { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 9px 12px; border-bottom: 1px solid var(--border); background: var(--surface); }
.result-batch-date, .record-actions { display: flex; align-items: center; gap: 8px; }
.result-batch-date > i { color: var(--color-primary); font-size: 17px; }
.result-batch-date > span:not(.badge) { font-weight: 700; font-size: 12.5px; }
.record-action { width: 30px; height: 30px; display: grid; place-items: center; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--surface); color: var(--text-2); cursor: pointer; transition: all .2s; }
.record-action.edit:hover { color: var(--color-primary-dark); border-color: var(--color-primary); background: var(--color-primary-soft); }
.record-action.delete:hover { color: var(--color-error); border-color: var(--color-error); background: #fef2f2; }
.result-badges { display: flex; flex-wrap: wrap; gap: 7px; padding: 12px; }
.test-result-badge, .anti-hla-result-badge { display: inline-flex; align-items: center; gap: 6px; min-height: 32px; padding: 4px 7px 4px 5px; border: 1px solid #bae6fd; border-radius: var(--radius-full); background: var(--color-primary-soft); color: var(--color-primary-dark); font-size: 13px; }
.test-result-category { padding-inline-end: 6px; border-inline-end: 1px solid rgba(3,105,161,.2); color: var(--text-2); }
.test-result-value { padding: 1px 7px; border-radius: var(--radius-full); background: var(--surface); color: var(--text-1); font-weight: 800; }
.test-result-badge button { width: 22px; height: 22px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 50%; background: rgba(255,255,255,.7); color: var(--text-2); cursor: pointer; }
.test-result-badge button:hover { color: var(--color-primary-dark); background: #fff; }
.test-result-badge button.delete:hover { color: var(--color-error); }
.anti-hla-result-badge { border-color: var(--border); background: var(--surface); }
.anti-hla-result-badge > .badge { padding: 2px 7px; }

/* ---- مودال Anti-HLA ---- */
.modal.anti-hla-modal {
  width: min(1120px, calc(100vw - 32px)); max-width: 1120px;
  min-height: min(720px, calc(100vh - 32px)); max-height: calc(100vh - 32px);
  display: flex; flex-direction: column; padding: 28px;
}
.anti-hla-modal-body { overflow-y: auto; flex: 1; padding: 4px 20px; }
.anti-hla-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; margin-top: 18px; }
.anti-hla-class-card { padding: 18px; border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--surface-ground); }
.anti-hla-class-card h4 { display: flex; align-items: center; gap: 7px; margin: 0 0 13px; font-size: 13px; }
.anti-hla-class-card .form-group:last-child { margin-bottom: 0; }
.anti-hla-none-option {
  display: flex; align-items: center; gap: 10px; margin-bottom: 14px; padding: 10px 12px;
  border: 1px dashed var(--border-strong); border-radius: var(--radius-md);
  background: var(--surface); cursor: pointer; transition: all .2s;
}
.anti-hla-none-option:hover, .anti-hla-none-option.checked { border-color: var(--color-primary); background: var(--color-primary-soft); }
.anti-hla-none-option input { width: 17px; height: 17px; accent-color: var(--color-primary); }
.anti-hla-none-option > span { display: flex; align-items: center; gap: 8px; }
.anti-hla-none-option strong { direction: ltr; color: var(--color-primary-dark); }
.anti-hla-none-option small { color: var(--text-2); }
.anti-hla-selection-summary { display: flex; align-items: center; gap: 7px; margin-top: 12px; padding: 9px 11px; border-radius: var(--radius-md); background: #eff6ff; color: var(--info-700); font-size: 13px; }
.modal.cdc-pra-modal {
  width: min(920px, calc(100vw - 32px)); max-width: 920px;
  max-height: calc(100vh - 32px); display: flex; flex-direction: column; padding: 28px;
}
.cdc-pra-modal .modal-header h3 { display: flex; align-items: center; gap: 9px; }
.cdc-pra-modal .modal-header h3 > i { color: var(--color-primary); font-size: 24px; }
.cdc-pra-modal-body { overflow-y: auto; flex: 1; padding: 4px 20px; }
.cdc-pra-modal-note { display: flex; align-items: center; gap: 8px; margin-bottom: 18px; padding: 11px 13px; border-radius: var(--radius-md); background: #eff6ff; color: var(--info-700); font-size: 14px; }
.cdc-pra-date-field { max-width: 520px; }
.cdc-pra-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; margin-top: 18px; }
.cdc-pra-modal .cdc-pra-card { background: var(--surface-ground); }
.cdc-pra-modal .cdc-pra-card h4 { display: flex; align-items: center; gap: 8px; }
.cdc-pra-modal .cdc-status-options { width: 100%; max-width: none; }
.cdc-pra-modal .cdc-value-field { max-width: none; }
.cdc-pra-modal .input-with-suffix.form-error-border .form-input,
.cdc-pra-modal .input-with-suffix.form-error-border > span { border-color: var(--color-error); }
.cdc-class-implicit-note { display: flex; align-items: center; gap: 5px; margin-top: 7px; color: var(--success-700); font-size: 13px; font-weight: 700; }
.cdc-implicit-alert { margin: 14px 0 0; }

/* ===================== ۶) تقویم دوزبانه (شمسی / میلادی) ===================== */
.dp { position: relative; }
.dp-mode { display: inline-flex; background: var(--surface-muted); border-radius: 9px; padding: 3px; gap: 2px; margin-bottom: 8px; }
.dp-mode-btn {
  border: none; background: transparent; padding: 5px 18px; border-radius: 7px;
  font-family: inherit; font-size: 12px; font-weight: 600; color: var(--text-2);
  cursor: pointer; transition: all .2s;
}
.dp-mode-btn.active { background: var(--color-primary); color: #fff; box-shadow: 0 2px 6px rgba(14,165,233,.35); }
.dp-field {
  display: flex; align-items: center; gap: 8px;
  border: 2px solid var(--border); border-radius: var(--radius-md);
  padding: 9px 12px; background: var(--surface); cursor: pointer; transition: all .2s;
}
.dp-field:hover { border-color: var(--color-primary-light); }
.dp.open .dp-field { border-color: var(--color-primary); box-shadow: 0 0 0 4px rgba(14,165,233,.12); }
.dp-field-icon { color: var(--color-primary); font-size: 18px; }
.dp-display {
  flex: 1; border: none; background: transparent; outline: none;
  text-align: center; font-family: inherit; font-size: 14px; font-weight: 700;
  color: var(--text-1); cursor: pointer;
}
.dp-display::placeholder { color: var(--text-3); font-weight: 400; }
.dp-clear { border: none; background: transparent; cursor: pointer; color: var(--text-3); font-size: 17px; padding: 0; line-height: 1; transition: color .2s; }
.dp-clear:hover { color: var(--color-error); }
.dp-caret { color: var(--text-3); transition: transform .2s; }
.dp-caret.rotated { transform: rotate(180deg); }
.dp-equiv { font-size: 11.5px; color: var(--text-3); margin-top: 5px; }
.dp-equiv b { color: var(--text-2); font-weight: 600; }
.dp-panel {
  position: absolute; top: calc(100% + 6px); right: 0; width: 302px;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius-lg); box-shadow: var(--shadow-3);
  z-index: 500; padding: 12px;
}
.dp-nav { display: flex; align-items: center; gap: 6px; margin-bottom: 10px; }
.dp-nav-btn {
  width: 30px; height: 30px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--surface-muted);
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  color: var(--text-2); transition: all .2s; flex-shrink: 0;
}
.dp-nav-btn:hover { background: var(--color-primary); border-color: var(--color-primary); color: #fff; }
.dp-select {
  flex: 1; padding: 6px 8px; border: 1px solid var(--border); border-radius: var(--radius-sm);
  background: var(--surface); font-family: inherit; font-size: 12.5px; font-weight: 600;
  cursor: pointer; outline: none; color: var(--text-1);
}
.dp-select:focus { border-color: var(--color-primary); }
.dp-weekdays { display: grid; grid-template-columns: repeat(7, 1fr); text-align: center; margin-bottom: 4px; }
.dp-weekdays span { font-size: 11px; font-weight: 700; color: var(--text-3); padding: 4px 0; }
.dp-weekday-holiday { color: var(--color-error) !important; }
.dp-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px; }
.dp-day {
  aspect-ratio: 1; border: none; background: transparent; border-radius: 9px;
  font-family: inherit; font-size: 13px; font-weight: 500; cursor: pointer;
  color: var(--text-1); transition: all .15s;
  display: flex; align-items: center; justify-content: center;
}
.dp-day:hover { background: var(--color-primary-soft); color: var(--color-primary-dark); transform: scale(1.1); }
.dp-day.muted { color: var(--text-3); opacity: .45; }
.dp-day.today { border: 1.5px solid var(--color-primary); font-weight: 800; }
.dp-day.selected { background: var(--grad-brand); color: #fff; font-weight: 700; box-shadow: var(--shadow-brand); }
.dp-day.selected:hover { color: #fff; }
.dp-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border); }
.dp-today-btn {
  display: inline-flex; align-items: center; gap: 6px;
  border: none; background: var(--color-primary-soft); color: var(--color-primary-dark);
  padding: 6px 14px; border-radius: var(--radius-sm);
  font-family: inherit; font-size: 12px; font-weight: 700; cursor: pointer; transition: all .2s;
}
.dp-today-btn:hover { background: var(--color-primary); color: #fff; }
.dp-clear-btn {
  border: none; background: transparent; color: var(--text-3);
  font-family: inherit; font-size: 12px; font-weight: 600; cursor: pointer; transition: color .2s;
}
.dp-clear-btn:hover { color: var(--color-error); }
.dp-pop-enter-active, .dp-pop-leave-active { transition: all .18s ease; transform-origin: top center; }
.dp-pop-enter-from, .dp-pop-leave-to { opacity: 0; transform: translateY(-6px) scale(.97); }

/* ===================== ۷) چندانتخابی چک‌باکسی ===================== */
.cms { position: relative; }
.cms-control {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  min-height: 42px; padding: 6px 12px;
  border: 2px solid var(--border); border-radius: var(--radius-md);
  background: var(--surface); cursor: pointer; transition: all .2s;
}
.cms-control:hover { border-color: var(--color-primary); }
.cms.open .cms-control { border-color: var(--color-primary); box-shadow: 0 0 0 4px rgba(14,165,233,.12); }
.cms.disabled .cms-control { opacity: .55; cursor: not-allowed; background: var(--surface-muted); }
.cms-values { display: flex; flex-wrap: wrap; gap: 5px; flex: 1; }
.cms-chip {
  display: inline-flex; align-items: center; gap: 5px;
  background: var(--color-primary-soft); color: var(--color-primary-dark);
  padding: 2px 9px; border-radius: var(--radius-sm); font-size: 12px; font-weight: 600;
}
.cms-chip i { font-size: 13px; cursor: pointer; }
.cms-chip i:hover { color: var(--color-error); }
.cms-more { background: var(--surface-muted); color: var(--text-2); cursor: pointer; }
.cms-placeholder { color: var(--text-3); font-size: 13px; flex: 1; }
.cms-arrow { font-size: 18px; color: var(--text-3); transition: transform .2s; flex-shrink: 0; }
.cms.open .cms-arrow { transform: rotate(180deg); }
.cms-panel {
  position: absolute; top: calc(100% + 4px); right: 0; left: 0;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius-md); box-shadow: var(--shadow-3);
  max-height: 230px; overflow-y: auto; z-index: 400; padding: 6px;
}
.cms-option { display: flex; align-items: center; gap: 9px; padding: 7px 10px; border-radius: var(--radius-sm); cursor: pointer; font-size: 13px; transition: background .15s; }
.cms-option:hover { background: var(--surface-muted); }
.cms-option.disabled { opacity: .35; cursor: not-allowed; }
.cms-option input[type="checkbox"] { width: 16px; height: 16px; accent-color: var(--color-primary); cursor: pointer; flex-shrink: 0; }
.cms-option span { flex: 1; }

/* ===================== ۸) استپر / تب / آکاردئون ===================== */
.stepper { display: flex; align-items: center; background: var(--surface-muted); border-radius: 30px; padding: 4px; }
.step-item {
  flex: 1; display: flex; align-items: center; justify-content: center; gap: 9px;
  padding: 10px 12px; border-radius: 26px;
  font-weight: 600; font-size: 13px; cursor: pointer; border: none;
  background: transparent; font-family: inherit; color: var(--text-2);
  transition: all .2s; white-space: nowrap;
}
.step-item:hover { background: rgba(255,255,255,.6); color: var(--color-primary); }
.step-item.active { background: var(--color-primary); color: #fff; box-shadow: 0 4px 12px -3px rgba(14,165,233,.5); }
.step-item.done { background: var(--surface); color: var(--color-success); }
.step-number {
  width: 26px; height: 26px; border-radius: 50%;
  background: rgba(255,255,255,.25);
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 700; flex-shrink: 0;
}
.step-item.done .step-number { background: var(--color-success); color: #fff; }

.tabs { display: flex; border-bottom: 2px solid var(--border); margin-bottom: 20px; gap: 4px; flex-wrap: wrap; }
.tab {
  padding: 10px 18px; background: transparent; border: none;
  font-weight: 600; color: var(--text-2); cursor: pointer;
  font-family: inherit; font-size: 13px; position: relative; white-space: nowrap;
  display: inline-flex; align-items: center; gap: 7px; transition: color .2s;
}
.tab:hover { color: var(--color-primary); }
.tab.active { color: var(--color-primary); }
.tab.active::after { content: ''; position: absolute; bottom: -2px; right: 0; left: 0; height: 2.5px; background: var(--color-primary); border-radius: 2px; }

.accordion { border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: visible; background: var(--surface); }
.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-item:last-child { border-bottom: none; }
.accordion-header {
  padding: 13px 16px; background: var(--surface-muted); cursor: pointer;
  display: flex; align-items: center; justify-content: space-between;
  font-weight: 700; font-size: 13.5px; transition: background .2s;
}
.accordion-header:hover { background: var(--border); }
.accordion-header > span { display: inline-flex; align-items: center; gap: 9px; }
.accordion-content { padding: 18px; display: none; }
.accordion-item.open .accordion-content { display: block; animation: fadeIn .25s; }
.accordion-item.open .accordion-header i.ri-arrow-down-s-line { transform: rotate(180deg); transition: transform .2s; }

/* ===================== ۹) جدول / نشان / هویت ===================== */
.data-table { width: 100%; border-collapse: collapse; background: var(--surface); border-radius: var(--radius-lg); overflow: hidden; }
.data-table thead th {
  background: var(--surface-muted); padding: 12px 14px; text-align: right;
  font-size: 12px; font-weight: 700; color: var(--text-2);
  border-bottom: 1px solid var(--border);
}
.data-table tbody td { padding: 12px 14px; border-bottom: 1px solid var(--border); font-size: 13px; }
.data-table tbody tr { transition: background .2s; }
.data-table tbody tr:hover { background: var(--surface-muted); }
.data-table tbody tr:last-child td { border-bottom: none; }
.data-table tbody tr:nth-child(even) { background: #fafbfc; }

.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 10px; border-radius: var(--radius-md);
  font-size: 12px; font-weight: 600; white-space: nowrap;
}
.badge-primary { background: var(--color-primary-soft); color: var(--color-primary-dark); }
.badge-success { background: #d1fae5; color: var(--success-700); }
.badge-warning { background: #fef3c7; color: var(--warning-700); }
.badge-danger { background: #fee2e2; color: var(--error-700); }
.badge-info { background: #dbeafe; color: var(--info-700); }
.badge-secondary { background: var(--surface-muted); color: var(--text-2); }

.avatar {
  width: 40px; height: 40px; border-radius: 50%;
  background: var(--grad-brand); color: #fff;
  display: inline-flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 14px; flex-shrink: 0;
}
.avatar.sm { width: 32px; height: 32px; font-size: 12px; }
.avatar.lg { width: 52px; height: 52px; font-size: 18px; }
.avatar.donor { background: var(--grad-donor); }

.identity-cell { display: flex; align-items: center; gap: 10px; }
.identity-cell-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.identity-name { font-weight: 700; font-size: 13px; }
.identity-subline { font-size: 12px; color: var(--text-2); }

.progress { height: 6px; background: var(--border); border-radius: 4px; overflow: hidden; }
.progress-bar { height: 100%; background: var(--grad-brand); border-radius: 4px; transition: width .4s; }
.progress-bar.success { background: var(--color-success); }
.progress-bar.warning { background: var(--color-warning); }
.progress-bar.danger { background: var(--color-error); }

/* ===================== ۱۰) جستجو و فیلتر لیست‌ها ===================== */
.list-search-row { display: flex; gap: 10px; align-items: center; }
.list-search-input { position: relative; flex: 1; min-width: 220px; }
.list-search-input > i { position: absolute; right: 13px; top: 50%; transform: translateY(-50%); color: var(--text-3); font-size: 17px; }
.list-search-input .form-input { padding-right: 40px; }
.list-filters { margin-top: 16px; padding-top: 16px; border-top: 1.5px dashed var(--border-strong); }
.list-filters-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.list-filters-title { font-size: 13px; font-weight: 700; color: var(--text-2); display: inline-flex; align-items: center; gap: 7px; }
.list-filters-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(165px, 1fr)); gap: 12px; }
.collapse-enter-active, .collapse-leave-active { transition: all .25s ease; }
.collapse-enter-from, .collapse-leave-to { opacity: 0; transform: translateY(-8px); }

/* ===================== ۱۱) مودال / هشدار / تهی ===================== */
.modal-overlay {
  position: fixed; inset: 0; background: rgba(15,23,42,.55);
  display: flex; align-items: center; justify-content: center;
  z-index: 1000; animation: fadeIn .2s; padding: 16px;
}
.modal {
  background: var(--surface); border-radius: var(--radius-xl); padding: 24px;
  width: 100%; max-width: 520px; box-shadow: var(--shadow-3); animation: slideUp .3s;
}
.modal-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }
.modal-header h3 { font-size: 17px; font-weight: 800; margin: 0; }
.modal-footer { display: flex; justify-content: flex-end; gap: 8px; margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--border); }
.modal-close {
  width: 32px; height: 32px; border-radius: 50%;
  background: var(--surface-muted); border: none; cursor: pointer;
  font-size: 18px; color: var(--text-2); transition: all .2s;
}
.modal-close:hover { background: #fee2e2; color: var(--color-error); }

.alert {
  padding: 13px 16px; border-radius: var(--radius-md);
  display: flex; align-items: flex-start; gap: 10px;
  margin-bottom: 16px; font-size: 13px; border-right: 4px solid;
}
.alert-info { background: #eff6ff; color: var(--info-700); border-color: var(--color-info); }
.alert-success { background: #f0fdf4; color: var(--success-700); border-color: var(--color-success); }
.alert-warning { background: #fffbeb; color: var(--warning-700); border-color: var(--color-warning); }
.alert-danger { background: #fef2f2; color: var(--color-error); border-color: var(--color-error); }

.empty-state {
  padding: 46px 20px; text-align: center;
  border: 2px dashed var(--border-strong); border-radius: var(--radius-lg);
  background: var(--surface-muted); transition: border-color .2s;
}
.empty-state:hover { border-color: var(--color-primary-light); }
.empty-state i { font-size: 44px; color: var(--text-3); margin-bottom: 12px; display: block; }
.empty-state h3 { font-size: 15.5px; margin-bottom: 5px; font-weight: 800; }
.empty-state p { font-size: 13px; color: var(--text-2); margin: 0; max-width: 420px; margin-inline: auto; }

/* ---- جای‌نگهدار تب‌های پروفایل ---- */
.tab-placeholder {
  border: 2px dashed var(--border-strong); border-radius: var(--radius-lg);
  background: var(--surface); padding: 70px 20px; text-align: center; transition: border-color .2s;
}
.tab-placeholder:hover { border-color: var(--color-primary-light); }
.tab-placeholder-icon {
  width: 74px; height: 74px; margin: 0 auto 16px; border-radius: 20px;
  background: var(--color-primary-soft); color: var(--color-primary-dark);
  display: flex; align-items: center; justify-content: center; font-size: 34px;
}
.tab-placeholder h3 { font-size: 17px; font-weight: 800; margin-bottom: 6px; }
.tab-placeholder p { color: var(--text-2); font-size: 13px; margin: 0; }
.placeholder-tile {
  border: 2px dashed var(--border-strong); border-radius: var(--radius-lg);
  padding: 30px 20px; text-align: center; background: var(--surface); transition: all .2s;
}
.placeholder-tile:hover { border-color: var(--color-primary); transform: translateY(-3px); box-shadow: var(--shadow-2); }
.placeholder-tile i { font-size: 34px; color: var(--color-primary); display: block; margin-bottom: 10px; }
.placeholder-tile h3 { font-size: 14px; margin-bottom: 4px; font-weight: 800; }
.placeholder-tile p { font-size: 12px; color: var(--text-2); margin: 0; }

/* ---- هدر پروفایل ---- */
.profile-header {
  background: var(--grad-brand);
  border-radius: var(--radius-xl); padding: 28px; color: #fff;
  display: flex; align-items: center; gap: 20px; margin-bottom: 20px;
  position: relative; overflow: hidden;
}
.profile-header.donor { background: var(--grad-donor); }
.profile-header::before {
  content: ''; position: absolute; top: -50%; right: -8%;
  width: 300px; height: 300px;
  background: radial-gradient(circle, rgba(255,255,255,.16) 0%, transparent 70%);
  border-radius: 50%;
}
.profile-avatar {
  width: 88px; height: 88px; border-radius: 50%;
  background: rgba(255,255,255,.2);
  display: flex; align-items: center; justify-content: center;
  font-size: 34px; font-weight: 800;
  border: 3px solid rgba(255,255,255,.35);
  position: relative; z-index: 1;
}
.profile-info { flex: 1; position: relative; z-index: 1; }
.profile-info h2 { font-size: 23px; font-weight: 900; margin-bottom: 8px; }
.profile-meta { display: flex; gap: 16px; flex-wrap: wrap; font-size: 13px; opacity: .95; }
.profile-meta-item { display: flex; align-items: center; gap: 5px; }

/* ===================== ۱۲) آزمایش‌ها (مودال) ===================== */
.rt-categories { display: flex; flex-wrap: wrap; gap: 6px; border-bottom: 2px solid var(--border); padding-bottom: 10px; margin: 4px 0 16px; }
.rt-cat-btn {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 7px 15px; border-radius: 22px; border: 1px solid transparent;
  background: var(--surface-muted); color: var(--text-2);
  font-family: inherit; font-size: 12.5px; font-weight: 600; cursor: pointer; transition: all .2s;
}
.rt-cat-btn i { font-size: 15px; }
.rt-cat-btn:hover { background: var(--color-primary-soft); color: var(--color-primary); }
.rt-cat-btn.active { background: var(--color-primary); color: #fff; box-shadow: 0 3px 9px rgba(14,165,233,.35); }
.rt-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 20px; }
.rt-row { display: flex; align-items: flex-start; gap: 10px; }
.rt-label { flex: 0 0 135px; display: flex; align-items: baseline; gap: 4px; padding-top: 9px; font-weight: 600; font-size: 13px; }
.rt-label small { color: var(--text-2); font-weight: 400; font-size: 13px; }
.rt-input-group { flex: 1; display: flex; flex-direction: column; }
.rt-input-group .form-input { padding: 7px 10px; }
.rt-hint { color: var(--text-2); font-size: 13px; margin-top: 3px; }
.rt-error { color: var(--color-error); font-size: 13px; margin-top: 3px; }
.rt-panel { padding: 4px 0; }
.rt-result-row { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; margin-bottom: 12px; }
.rt-result-label { font-weight: 700; font-size: 13px; }
.rt-subtitle { margin: 0 0 12px; color: var(--color-primary-dark); font-size: 14px; font-weight: 700; }
.rt-urine-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 20px; }
.rt-urine-item { display: flex; flex-direction: column; gap: 5px; }
.rt-urine-item label { font-size: 12.5px; font-weight: 600; }
.vt-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px 20px; direction: ltr; background: var(--surface-ground); padding: 14px; border-radius: var(--radius-lg); }
.vt-row { display: flex; align-items: center; gap: 10px; padding: 4px 0; border-bottom: 1px solid var(--border); }
.vt-name { flex: 0 0 155px; font-weight: 600; font-size: 12.5px; text-align: left; }
.vt-input { flex: 1; }
.vt-input .form-input { padding: 6px 10px; width: 100%; }

/* ---- تاییدیه‌ها ---- */
.specialties-header { display: flex; flex-wrap: wrap; gap: 8px; border-bottom: 2px solid var(--border); padding-bottom: 10px; margin-bottom: 16px; }
.specialty-tab {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 8px 16px; border-radius: 30px; border: 1px solid transparent;
  background: var(--surface-muted); color: var(--text-2);
  font-family: inherit; font-size: 13px; font-weight: 600; cursor: pointer; transition: all .2s;
}
.specialty-tab i { font-size: 16px; }
.specialty-tab.approved { background: rgba(16,185,129,.16); border-color: rgba(16,185,129,.5); color: var(--success-700); }
.specialty-tab.rejected { background: rgba(239,68,68,.16); border-color: rgba(239,68,68,.5); color: #b91c1c; }
.specialty-tab.on-hold { background: rgba(245,158,11,.16); border-color: rgba(245,158,11,.5); color: #b45309; }
.specialty-tab.active { transform: translateY(-2px); box-shadow: var(--shadow-2); font-weight: 800; border-width: 2px; }
.specialty-detail { border-radius: var(--radius-lg); padding: 16px; border: 1px solid var(--border); transition: all .25s; }
.specialty-detail.approved { border-right: 4px solid var(--color-success); background: #f0fdf4; }
.specialty-detail.rejected { border-right: 4px solid var(--color-error); background: #fef2f2; }
.specialty-detail.on-hold { border-right: 4px solid var(--color-warning); background: #fffbeb; }

/* ---- استعلام کد ملی ---- */
.lookup-result { padding: 16px; background: var(--surface-muted); border-radius: var(--radius-lg); border: 1px solid var(--border); margin-top: 12px; }
.lookup-result-header { display: flex; align-items: center; gap: 12px; padding-bottom: 12px; border-bottom: 1px solid var(--border); margin-bottom: 12px; }
.lookup-info { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 12px; }
.lookup-info-item { display: flex; flex-direction: column; gap: 3px; }
.lookup-info-item .label { font-size: 11px; color: var(--text-3); }
.lookup-info-item .value { font-size: 13px; font-weight: 600; }

/* ===================== ۱۳) اعلان (Toast) ===================== */
.toast-container { position: fixed; top: 78px; left: 24px; z-index: 2000; display: flex; flex-direction: column; gap: 8px; }
.toast {
  background: var(--surface); border-radius: var(--radius-md);
  padding: 12px 16px; box-shadow: var(--shadow-3);
  display: flex; align-items: center; gap: 10px; min-width: 280px;
  animation: slideInLeft .3s; border-right: 4px solid;
}
.toast.success { border-color: var(--color-success); }
.toast.error { border-color: var(--color-error); }
.toast.warning { border-color: var(--color-warning); }
.toast.info { border-color: var(--color-info); }

/* ===================== ۱۴) ابزارهای کمکی ===================== */
.checkbox-wrap { display: flex; align-items: center; gap: 8px; cursor: pointer; font-size: 13px; }
.checkbox-wrap input[type="checkbox"], .checkbox-wrap input[type="radio"] { width: 17px; height: 17px; accent-color: var(--color-primary); cursor: pointer; }
.text-center { text-align: center; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: 4px; } .gap-2 { gap: 8px; } .gap-3 { gap: 12px; } .gap-4 { gap: 16px; }
.mb-1 { margin-bottom: 4px; } .mb-2 { margin-bottom: 8px; } .mb-3 { margin-bottom: 12px; } .mb-4 { margin-bottom: 16px; }
.mt-2 { margin-top: 8px; } .mt-3 { margin-top: 12px; } .mt-4 { margin-top: 16px; }
.w-full { width: 100%; }
.font-bold { font-weight: 700; }
.text-sm { font-size: 13px; } .text-xs { font-size: 12px; }
.text-muted { color: var(--text-3); }
.text-secondary { color: var(--text-2); }
.text-primary { color: var(--color-primary); }
.text-success { color: var(--color-success); }
.text-warning { color: var(--color-warning); }
.text-danger { color: var(--color-error); }

/* ---- ترنزیشن‌های روتر ---- */
.fade-enter-active, .fade-leave-active { transition: opacity .15s; }
.fade-enter-from, .fade-leave-to { opacity: 0; }
.slide-enter-active, .slide-leave-active { transition: all .25s; }
.slide-enter-from { opacity: 0; transform: translateX(20px); }
.slide-leave-to { opacity: 0; transform: translateX(-20px); }

/* ===================== ۱۵) واکنش‌گرایی ===================== */
@media (max-width: 1200px) {
  .grid-3, .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .form-grid-3, .form-grid-4 { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 1180px) {
  .identity-primary-grid.is-foreign > .form-group { grid-column: span 6 !important; }
  .identity-primary-grid.is-foreign > .form-group:last-child { grid-column: span 12 !important; }
}
@media (max-width: 900px) {
  .topbar-user-text { display: none; }
  .identity-details-grid > .form-group:nth-child(-n+3),
  .personal-profile-grid > .form-group:nth-child(-n+3) { grid-column: span 6; }
  .identity-details-grid > .form-group:nth-child(3),
  .personal-profile-grid > .form-group:nth-child(3) { grid-column: span 12; }
}
@media (max-width: 768px) {
  .rt-grid, .rt-urine-grid, .vt-grid { grid-template-columns: 1fr; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .form-grid, .form-grid-3, .form-grid-4 { grid-template-columns: 1fr; }
  .list-search-row { flex-wrap: wrap; }
  .stepper { flex-wrap: wrap; border-radius: var(--radius-lg); }
  .create-person-page .form-grid > .form-group,
  .identity-primary-grid > .form-group,
  .identity-primary-grid.is-foreign > .form-group,
  .identity-primary-grid.is-foreign > .form-group:last-child,
  .identity-details-grid > .form-group:nth-child(n),
  .personal-profile-grid > .form-group:nth-child(n) { grid-column: span 12 !important; }
  .anti-hla-columns, .cdc-pra-grid, .cdc-pra-columns { grid-template-columns: 1fr; }
  .form-actions, .form-actions > .flex { flex-wrap: wrap; }
  .sticky-form-footer { margin-inline: -8px; padding: 10px; }
  .form-action-end { width: 100%; }
  .form-next-button { flex: 1; min-width: 0; }
  .risk-disclosure-trigger { grid-template-columns: 1fr auto; }
  .risk-disclosure-summary { grid-column: 1 / -1; grid-row: 2; }
  .modal.anti-hla-modal { width: calc(100vw - 20px); min-height: 0; max-height: calc(100vh - 20px); padding: 18px; }
  .anti-hla-modal-body { padding-inline: 2px; }
  .modal.cdc-pra-modal { width: calc(100vw - 20px); max-height: calc(100vh - 20px); padding: 18px; }
  .cdc-pra-modal-body { padding-inline: 2px; }
}


import * as jalaali from 'jalaali-js'

/**
 * Convert Gregorian date to Jalali
 */
export const gregorianToJalali = (gy, gm, gd) => {
  if (jalaali?.toJalaali) {
    const r = jalaali.toJalaali(gy, gm, gd)
    return { jy: r.jy, jm: r.jm, jd: r.jd }
  }
  // Fallback implementation
  const g_d_m = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
  let gy2 = gm > 2 ? gy + 1 : gy
  let days = 355666 + 365 * gy + Math.floor((gy2 + 3) / 4) - Math.floor((gy2 + 99) / 100) + Math.floor((gy2 + 399) / 400) + gd + g_d_m[gm - 1]
  let jy = -1595 + 33 * Math.floor(days / 12053)
  days %= 12053
  jy += 4 * Math.floor(days / 1461)
  days %= 1461
  if (days > 365) {
    jy += Math.floor((days - 1) / 365)
    days = (days - 1) % 365
  }
  const jm = days < 186 ? 1 + Math.floor(days / 31) : 7 + Math.floor((days - 186) / 30)
  const jd = 1 + (days < 186 ? days % 31 : (days - 186) % 30)
  return { jy, jm, jd }
}

/**
 * Convert Jalali date to Gregorian
 */
export const jalaliToGregorian = (jy, jm, jd) => {
  if (jalaali?.toGregorian) {
    const r = jalaali.toGregorian(jy, jm, jd)
    return { gy: r.gy, gm: r.gm, gd: r.gd }
  }
  // Fallback implementation
  let jy2 = jy + 1595
  let days = -355668 + 365 * jy2 + Math.floor(jy2 / 33) * 8 + Math.floor(((jy2 % 33) + 3) / 4) + jd + (jm < 7 ? (jm - 1) * 31 : (jm - 7) * 30 + 186)
  let gy = 400 * Math.floor(days / 146097)
  days %= 146097
  if (days > 36524) {
    gy += 100 * Math.floor(--days / 36524)
    days %= 36524
    if (days >= 365) days++
  }
  gy += 4 * Math.floor(days / 1461)
  days %= 1461
  if (days > 365) {
    gy += Math.floor((days - 1) / 365)
    days = (days - 1) % 365
  }
  let gd = days + 1
  const g_d_m = [0, 31, ((gy % 4 === 0 && gy % 100 !== 0) || (gy % 400 === 0)) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
  let gm
  for (gm = 0; gm < 13 && gd > g_d_m[gm]; gm++) gd -= g_d_m[gm]
  return { gy, gm, gd }
}

/**
 * Convert Jalali string (YYYY-MM-DD) to Gregorian string
 */
export const jalaliStrToGregorian = (str) => {
  if (!str || !/^\d{4}-\d{2}-\d{2}$/.test(str)) return ''
  const [jy, jm, jd] = str.split('-').map(Number)
  const r = jalaliToGregorian(jy, jm, jd)
  if (!r || !r.gy) return ''
  const pad = n => String(n).padStart(2, '0')
  return `${r.gy}-${pad(r.gm)}-${pad(r.gd)}`
}

/**
 * Convert Gregorian string (YYYY-MM-DD) to Jalali string
 */
export const gregorianStrToJalali = (str) => {
  if (!str || !/^\d{4}-\d{2}-\d{2}$/.test(str)) return ''
  const [gy, gm, gd] = str.split('-').map(Number)
  const r = gregorianToJalali(gy, gm, gd)
  if (!r || !r.jy) return ''
  const pad = n => String(n).padStart(2, '0')
  return `${r.jy}-${pad(r.jm)}-${pad(r.jd)}`
}

/**
 * Get length of a Jalali month
 */
export const jMonthLength = (jy, jm) => {
  if (jalaali?.jalaaliMonthLength) return jalaali.jalaaliMonthLength(jy, jm)
  if (jm <= 6) return 31
  if (jm <= 11) return 30
  const g = jalaliToGregorian(jy, 12, 30)
  const back = gregorianToJalali(g.gy, g.gm, g.gd)
  return back.jy === jy ? 30 : 29
}

/**
 * Convert digits to Persian/Farsi
 */
export const toFaDigits = (v) => String(v).replace(/\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[d])

/**
 * Pad number with leading zero
 */
export const pad2 = n => String(n).padStart(2, '0')

/**
 * Jalali months names
 */
export const JALALI_MONTHS = ['فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند']

/**
 * Gregorian months names in Persian
 */
export const GREGORIAN_MONTHS_FA = ['ژانویه', 'فوریه', 'مارس', 'آوریل', 'مه', 'ژوئن', 'ژوئیه', 'اوت', 'سپتامبر', 'اکتبر', 'نوامبر', 'دسامبر']

/**
 * Weekday names in Persian
 */
export const WEEKDAYS_FA = ['یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه']

/**
 * Weekday letters (for calendar headers)
 */
export const WEEKDAY_LETTERS = ['ش', 'ی', 'د', 'س', 'چ', 'پ', 'ج']

/**
 * Get current date in both Gregorian and Jalali formats
 */
export const getCurrentDate = () => {
  const now = new Date()
  const j = gregorianToJalali(now.getFullYear(), now.getMonth() + 1, now.getDate())
  return {
    gregorian: toFaDigits(`${now.getFullYear()}/${pad2(now.getMonth() + 1)}/${pad2(now.getDate())}`),
    jalali: `${WEEKDAYS_FA[now.getDay()]} ${toFaDigits(j.jy)}/${toFaDigits(j.jm)}/${toFaDigits(j.jd)}`
  }
}

/**
 * Format date string to Persian Jalali format
 */
export const formatFaDate = (dateStr) => {
  if (!dateStr) return '—'
  try {
    const [y, m, d] = String(dateStr).slice(0, 10).split('-').map(Number)
    const j = gregorianToJalali(y, m, d)
    return `${toFaDigits(j.jy)}/${toFaDigits(j.jm)}/${toFaDigits(j.jd)}`
  } catch (e) {
    return dateStr
  }
}


/**
 * Validate Iranian National ID
 */
export const nationalIdChecker = (id) => {
  try {
    if (!/^\d{10}$/.test(id)) return false
    if (/^(\d)\1{9}$/.test(id)) return false
    let sum = 0
    for (let i = 0; i < 9; i++) sum += parseInt(id[i]) * (10 - i)
    const remainder = sum % 11
    const lastDigit = parseInt(id[9])
    if (remainder < 2) return lastDigit === remainder
    return lastDigit === (11 - remainder)
  } catch (e) {
    return false
  }
}

/**
 * Normalize national ID input (convert Persian/Arabic digits to English)
 */
export const normalizeNationalId = (v) => {
  return String(v || '')
    .replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))
    .replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/\D/g, '')
    .trim()
}

/**
 * Normalize Iranian mobile number
 */
export const normalizeIranianMobile = (v) => {
  const digits = String(v || '')
    .replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))
    .replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/\D/g, '')
  if (!digits) return ''
  if (digits.length === 10 && !digits.startsWith('0')) return ('0' + digits).slice(0, 11)
  return digits.slice(0, 11)
}

/**
 * Validate Iranian mobile number format
 */
export const isValidIranianMobile = (v) => /^09\d{9}$/.test(String(v || '').trim())

/**
 * Convert Persian and Arabic digits inside any input to Latin digits.
 * Text is preserved so it can also be used for qualitative lab results.
 */
export const normalizeLocalizedDigits = (v) => String(v ?? '')
  .replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))
  .replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
  .replace(/٫/g, '.')
  .replace(/٬/g, ',')

/**
 * Normalize a localized positive decimal number to one Latin representation.
 */
export const normalizeLocalizedNumber = (v) => {
  const normalized = normalizeLocalizedDigits(v)
    .replace(/[,\s]/g, '')
    .replace(/[^0-9.]/g, '')
  const [integer = '', ...decimals] = normalized.split('.')
  return decimals.length ? `${integer}.${decimals.join('')}` : integer
}

/**
 * Normalize a localized signed decimal while preserving one leading minus.
 */
export const normalizeLocalizedSignedNumber = (v) => {
  const compact = normalizeLocalizedDigits(v)
    .replace(/[,\s]/g, '')
    .replace(/[^0-9.\-]/g, '')
  const negative = compact.startsWith('-')
  const unsigned = compact.replace(/-/g, '')
  const [integer = '', ...decimals] = unsigned.split('.')
  const number = decimals.length ? `${integer}.${decimals.join('')}` : integer
  return `${negative ? '-' : ''}${number}`
}

/**
 * Normalize ranges used by urine microscopy fields, for example ۱-۳ → 1-3.
 */
export const normalizeLocalizedNumberRange = (v) => {
  const normalized = normalizeLocalizedDigits(v)
    .replace(/[–—]/g, '-')
    .replace(/\s/g, '')
    .replace(/[^0-9.\-]/g, '')
  const parts = normalized.split('-').slice(0, 2)
  return parts.map(part => normalizeLocalizedNumber(part)).join('-')
}


